#!/usr/bin/env python3
"""
Test all models from a JSON config file against an OpenAI-compatible
/chat/completions endpoint.

Usage:
    python test_models.py models.json

Expected JSON formats (either is fine):
1) ["model-a", "model-b"]
2) {"models": ["model-a", "model-b"]}
"""

import sys
import json
import time
import urllib.request
import urllib.error

API_URL = "http://127.0.0.1:4000/v1/chat/completions"
PROMPT = "Reply with exactly one word: OK"
TIMEOUT_SECONDS = 30
MAX_TOKENS = 20


def load_models(path):
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)

    if isinstance(data, list):
        models = data
    elif isinstance(data, dict) and isinstance(data.get("models"), list):
        models = data["models"]
    else:
        raise ValueError(
            "Invalid JSON format. Use either a list of models or {'models': [...]}."
        )

    models = [m for m in models if isinstance(m, str) and m.strip()]
    if not models:
        raise ValueError("No valid model names found in config.")
    return models


def post_chat_completion(payload, timeout):
    body = json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(
        API_URL,
        data=body,
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        raw = resp.read().decode("utf-8", errors="replace")
        return json.loads(raw)


def extract_text(resp_json):
    try:
        return (
            resp_json["choices"][0]["message"]["content"]
            if resp_json.get("choices")
            else ""
        )
    except Exception:
        return ""


def test_model(model_name):
    # First attempt includes temperature
    payload = {
        "model": model_name,
        "messages": [{"role": "user", "content": PROMPT}],
        "max_tokens": MAX_TOKENS,
        "temperature": 0,
    }

    start = time.time()
    try:
        resp = post_chat_completion(payload, TIMEOUT_SECONDS)
        latency = time.time() - start
        text = extract_text(resp)
        return True, latency, text
    except urllib.error.HTTPError as e:
        # Check if temperature is unsupported, then retry without it
        err_body = ""
        try:
            err_body = e.read().decode("utf-8", errors="replace")
        except Exception:
            pass

        lowered = err_body.lower()
        if "temperature" in lowered and (
            "unsupported" in lowered
            or "not supported" in lowered
            or "unknown" in lowered
            or "invalid" in lowered
        ):
            retry_payload = {
                "model": model_name,
                "messages": [{"role": "user", "content": PROMPT}],
                "max_tokens": MAX_TOKENS,
            }
            retry_start = time.time()
            try:
                resp = post_chat_completion(retry_payload, TIMEOUT_SECONDS)
                latency = time.time() - retry_start
                text = extract_text(resp)
                return True, latency, text
            except Exception as e2:
                latency = time.time() - retry_start
                return False, latency, f"ERROR: {type(e2).__name__}"
        else:
            latency = time.time() - start
            return False, latency, f"HTTP {e.code}"
    except Exception as e:
        latency = time.time() - start
        return False, latency, f"ERROR: {type(e).__name__}"


def truncate(text, n=50):
    text = (text or "").replace("\n", " ").strip()
    if len(text) <= n:
        return text
    return text[: n - 3] + "..."


def print_table(results):
    # Determine widths
    model_w = max(len("Model"), max((len(r["model"]) for r in results), default=5))
    status_w = len("Status")
    latency_w = len("Latency")
    response_w = len("Response")

    header = (
        f"{'Model'.ljust(model_w)}  "
        f"{'Status'.ljust(status_w)}  "
        f"{'Latency'.ljust(latency_w)}  "
        f"{'Response'.ljust(response_w)}"
    )
    sep = "-" * len(header)
    print(header)
    print(sep)

    for r in results:
        print(
            f"{r['model'].ljust(model_w)}  "
            f"{r['status'].ljust(status_w)}  "
            f"{r['latency']:.2f}s".ljust(latency_w + 1) + " "
            f"{truncate(r['response'], 50)}"
        )


def main():
    if len(sys.argv) != 2:
        print("Usage: python test_models.py <models.json>")
        sys.exit(1)

    try:
        models = load_models(sys.argv[1])
    except Exception as e:
        print(f"Failed to load models: {e}")
        sys.exit(1)

    results = []
    ok_count = 0
    fail_count = 0

    for model in models:
        success, latency, text = test_model(model)
        status = "✅ PASS" if success else "❌ FAIL"
        if success:
            ok_count += 1
        else:
            fail_count += 1

        results.append(
            {
                "model": model,
                "status": status,
                "latency": latency,
                "response": text,
            }
        )

    print_table(results)
    print()
    print(f"Total: {len(models)} models | ✅ {ok_count} working | ❌ {fail_count} failed")


if __name__ == "__main__":
    main()
